15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
30	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    /**
36	     * Derives the owner's age band from the birth date, computed as the owner's age on the
37	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
38	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
39	     * date is absent, so an owner created without a birth date carries no age band.
40	     */
41	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
42	        java.time.LocalDate birthDate = owner.getBirthDate();
43	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
44	        if (birthDate == null || registrationDate == null) {
45	            return null;
46	        }
47	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
48	        if (age < 18) {
49	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
50	        }
51	        if (age < 65) {
52	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
53	        }
54	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
55	    }
56	
57	    /**
58	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
59	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
60	     */
61	    default Integer checkDigit(Owner owner) {
62	        String customerCode = owner.getCustomerCode();
63	        if (customerCode == null) {
64	            return null;
65	        }
66	        int sum = 0;
67	        boolean dbl = true;
68	        for (int i = customerCode.length() - 1; i >= 0; i--) {
69	            char c = customerCode.charAt(i);
70	            if (c < '0' || c > '9') {
71	                continue;
72	            }
73	            int d = c - '0';
74	            if (dbl) {
75	                d *= 2;
76	                if (d > 9) {
77	                    d -= 9;
78	                }
79	            }
80	            sum += d;
81	            dbl = !dbl;
82	        }
83	        return (10 - (sum % 10)) % 10;
84	    }
85	
86	    /**
87	     * Derives the owner's duplicate-detection identity key, formatted
88	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The email and household-id segments are
89	     * empty when the respective field is absent. The telephone and email are already stored in their
90	     * normalized (E.164 / lower-cased) form, so the stored values are used directly. This is the single
91	     * key against which owner duplicates are detected: two owners collide only when their whole keys
92	     * match.
93	     */
94	    default String identityKey(Owner owner) {
95	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
96	        String email = owner.getEmail() == null ? "" : owner.getEmail();
97	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
98	        return telephone + "|" + email + "|" + householdId;
99	    }
100	
101	    /**
102	     * Fixed city-to-region table used to derive an owner's locality.
103	     */
104	    java.util.Map<String, String> CITY_REGION =
105	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
106	
107	    /**
108	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
109	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
110	     */
111	    java.util.Map<String, int[]> REGION_POSTCODES =
112	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
113	
114	    /**
115	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
116	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
117	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
118	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
119	     * {@code "UNKNOWN"} when neither source resolves a region.
120	     */
121	    default String locality(Owner owner) {
122	        String customerCode = owner.getCustomerCode();
123	        if (customerCode != null) {
124	            int dash = customerCode.indexOf('-');
125	            String region = dash >= 0 ? customerCode.substring(0, dash) : customerCode;
126	            if (!region.isEmpty()) {
127	                return region;
128	            }
129	        }
130	        String postcode = owner.getPostcode();
131	        if (postcode != null) {
132	            try {
133	                int value = Integer.parseInt(postcode.trim());
134	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
135	                    int[] range = entry.getValue();
136	                    if (value >= range[0] && value <= range[1]) {
137	                        return entry.getKey();
138	                    }
139	                }
140	            }
141	            catch (NumberFormatException ex) {
142	                // Not a numeric postcode; fall back to the city table below.
143	            }
144	        }
145	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
146	    }
147	
148	    /**
149	     * Known E.164 country calling codes, longest first, used to split a stored E.164 telephone into
150	     * its country code and national digits when formatting {@link #telephoneDisplay(Owner)}.
151	     */
152	    String[] TELEPHONE_COUNTRY_CODES = {"61", "1"};
153	
154	    /**
155	     * Formats the owner's stored E.164 telephone for humans: the country code, a space, then the
156	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
157	     * The country code is recognised from the {@link #TELEPHONE_COUNTRY_CODES} table; when none matches,
158	     * all digits after the {@code '+'} are treated as the national number. Returns {@code null} when the
159	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164 number.
160	     */
161	    default String telephoneDisplay(Owner owner) {
162	        String telephone = owner.getTelephone();
163	        if (telephone == null) {
164	            return null;
165	        }
166	        if (!telephone.startsWith("+")) {
167	            return telephone;
168	        }
169	        String digits = telephone.substring(1);
170	        if (!digits.chars().allMatch(Character::isDigit)) {
171	            return telephone;
172	        }
173	        String countryCode = "";
174	        for (String code : TELEPHONE_COUNTRY_CODES) {
175	            if (digits.startsWith(code) && digits.length() > code.length()) {
176	                countryCode = code;
177	                break;
178	            }
179	        }
180	        String national = digits.substring(countryCode.length());
181	        StringBuilder grouped = new StringBuilder();
182	        for (int i = 0; i < national.length(); i++) {
183	            if (i > 0 && i % 3 == 0) {
184	                grouped.append(' ');
185	            }
186	            grouped.append(national.charAt(i));
187	        }
188	        return "+" + countryCode + " " + grouped;
189	    }
190	
191	    /**
192	     * Derives the owner's preferred contact channel: {@code "EMAIL"} when an email address is
193	     * present (non-blank), otherwise {@code "PHONE"}.
194	     */
195	    default String contactPreference(Owner owner) {
196	        String email = owner.getEmail();
197	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
198	    }
199	
200	    /**
201	     * Computes the owner's membership points. Starts at {@code 0} and adds {@code 2} when an email
202	     * is present, {@code 1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}),
203	     * {@code 2} for a household of {@code 3} or more ({@code householdSize}), and {@code 3} when the
204	     * owner's tenure exceeds {@code 365} days (measured from the {@code registrationDate} to the
205	     * current date).
206	     */
207	    default Integer membershipPoints(Owner owner) {
208	        Integer namesakeCount = owner.getNamesakeCount();
209	        String email = owner.getEmail();
210	        Integer householdSize = owner.getHouseholdSize();
211	        int points = 0;
212	        if (email != null && !email.isBlank()) {
213	            points += 2;
214	        }
215	        if (namesakeCount != null && namesakeCount == 0) {
216	            points += 1;
217	        }
218	        if (householdSize != null && householdSize >= 3) {
219	            points += 2;
220	        }
221	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
222	        boolean hasTenure = registrationDate != null
223	            && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now()) > 365;
224	        if (hasTenure) {
225	            points += 3;
226	        }
227	        return points;
228	    }
229	
230	    /**
231	     * Derives the owner's membership level, a number from 1 to 4, from the owner's
232	     * {@link #membershipPoints(Owner) membership points}: level {@code 1} for {@code 0-1} points,
233	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
234	     */
235	    default Integer membershipLevel(Owner owner) {
236	        int points = membershipPoints(owner);
237	        if (points <= 1) {
238	            return 1;
239	        }
240	        if (points <= 3) {
241	            return 2;
242	        }
243	        if (points <= 5) {
244	            return 3;
245	        }
246	        return 4;
247	    }
248	
